#include <stdio.h>

int main(void) {
    int wins = 0;
    char line[16];

    for (int i = 0; i < 6; i++) {
        if (scanf("%15s", line) == 1) {
            if (line[0] == 'V') {
                wins++;
            }
        }
    }

    if (wins >= 5) {
        printf("1\n");
    } else if (wins >= 3) {
        printf("2\n");
    } else if (wins >= 1) {
        printf("3\n");
    } else {
        printf("-1\n");
    }

    return 0;
}
